/* --------------------------------------------------- */
/* 2. الخط الأزرق الملكي السفلي (بالطريقة المضمونة) */
/* --------------------------------------------------- */
.widget.number-widget-box::after {
    content: '' !important;
    position: absolute !important;
    bottom: 0 !important;
    left: 0 !important;
    width: 100% !important;
    height: 3px !important; /* سمك الخط الأزرق */
