  /* ==========================================================================
   * ترويسة قسم الوعاظ - Frappe Custom Block Script (Header Module)
   * ========================================================================== */

  var root = typeof root_element !== 'undefined' ? root_element : document.querySelector('.tq-theme-oceanic') || document;

  // التهيئة وضمان عدم التكرار
