  root.__waed_header_bound = true;

})();

style:
/* ==========================================================================
   نظام الخطوط الموحد: GE SS Two للنصوص و Cairo حصرياً للأرقام القياسية (1234)
   Modern Minimal + Editorial/Swiss Header Style
   ========================================================================== */
@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@300;400;500;600;700;800;900&display=swap');

.tq-theme-oceanic {
  --tq-font:          'GE SS Two';

  /* ألوان الأسطح النظيفة */
  --tq-bg:            transparent;
  --tq-surface:       #ffffff;
  --tq-border:        #e2e8f0;

  /* حبر النصوص */
  --tq-ink:           #0f172a;
  --tq-ink-soft:      #334155;
  --tq-ink-faint:     #64748b;

  /* ألوان التمييز */
  --tq-accent:        #0284c7;
  --tq-accent-light:  #38bdf8;
  --tq-accent-subtle: #f0f9ff;
  --tq-accent-border: #bae6fd;

  /* المقاييس الهندسية */
  --tq-radius-md:     12px;
  --tq-radius-lg:     16px;

  --tq-space-2:       8px;
  --tq-space-3:       14px;
  --tq-space-4:       20px;
  --tq-space-5:       28px;

  /* الظلال الخفيفة */
  --tq-shadow-sm:     0 1px 3px 0 rgba(15, 23, 42, 0.03), 0 1px 2px -1px rgba(15, 23, 42, 0.02);

  font-family: var(--tq-font) !important;
  color: var(--tq-ink);
  background: var(--tq-bg);
  direction: rtl;
  text-align: right;
  box-sizing: border-box;
  -webkit-font-smoothing: antialiased;
}

/* 1. تطبيق خط GE SS Two لجميع النصوص والعناصر بالكامل */
.tq-theme-oceanic,
.tq-theme-oceanic *,
.tq-theme-oceanic *::before,
.tq-theme-oceanic *::after,
.tq-theme-oceanic h1,
.tq-theme-oceanic p,
.tq-theme-oceanic span {
  font-family: 'GE SS Two' !important;
  box-sizing: border-box;
}

/* 2. استثناء الأرقام فقط: خط Cairo الصريح والأرقام القياسية 1234 دائماً */
.tq-count-value,
.tq-count-value *,
.num,
.number,
.digits,
.stat-number,
[data-num] {
  font-family: 'GE SS Two' !important;
  font-feature-settings: "locl" 0, "numr" 0, "lnum" 1, "tnum" 1 !important;
  font-variant-numeric: lining-nums tabular-nums !important;
  direction: ltr !important;
  unicode-bidi: isolate !important;
  display: inline-block;
}

.tq-theme-oceanic .app-number,
.tq-theme-oceanic input[type="number"],
.tq-theme-oceanic input[inputmode="numeric"],
.tq-theme-oceanic input[inputmode="decimal"],
.tq-theme-oceanic input[type="tel"] { 
  font-family: 'Cairo' !important; 
  font-feature-settings: "locl" 0, "lnum" 1, "tnum" 1 !important; 
  font-variant-numeric: lining-nums tabular-nums !important; 
  direction: ltr; 
  unicode-bidi: isolate; 
}

/* إزالة أي خط سفلي */
.tq-theme-oceanic a,
.tq-theme-oceanic a:hover,
.tq-theme-oceanic a:focus,
.tq-theme-oceanic a:active,
.tq-theme-oceanic a:visited {
  text-decoration: none !important;
}

/* ============================================================
   تنسيقات الهيدر الرئيسي (Minimal Swiss Enterprise Header)
   ============================================================ */
.twd-header {
  width: 100%;
  margin-bottom: 16px;
}

.twd-header__hero {
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--tq-space-4);
  padding: 24px var(--tq-space-5);
  border-radius: var(--tq-radius-lg);
  background: var(--tq-surface);
  box-shadow: var(--tq-shadow-sm);
  border: 1px solid var(--tq-border);
}

.twd-header__content {
  position: relative;
  z-index: 2;
  max-width: 720px;
}

.twd-header__eyebrow {
  display: inline-flex;
  align-items: center;
  font-size: 0.76rem;
  font-weight: 800;
  color: var(--tq-accent);
  letter-spacing: 0.01em;
  margin-bottom: var(--tq-space-2);
  background: var(--tq-accent-subtle);
  padding: 2px 10px;
  border-radius: 6px;
  border: 1px solid var(--tq-accent-border);
}

.twd-header__title {
  font-size: 1.55rem;
  font-weight: 900;
  color: var(--tq-ink);
  margin: 0 0 var(--tq-space-2) 0;
  line-height: 1.25;
}

.twd-header__subtitle {
  font-size: 0.86rem;
  font-weight: 500;
  color: var(--tq-ink-faint);
  margin: 0;
  line-height: 1.6;
}

.twd-header__seal {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 54px;
  height: 54px;
  border-radius: var(--tq-radius-md);
  background: var(--tq-accent-subtle);
  border: 1px solid var(--tq-accent-border);
  color: var(--tq-accent);
  flex-shrink: 0;
}

.twd-header__seal svg {
  width: 28px;
  height: 28px;
}

/* التجاوب مع الشاشات الصغيرة */
@media (max-width: 768px) {
  .twd-header__hero {
    flex-direction: column;
    align-items: flex-start;
    padding: 18px 16px;
    gap: 14px;
  }
  
  .twd-header__title {
    font-size: 1.35rem;
  }

  .twd-header__subtitle {
    font-size: 0.82rem;
  }

  .twd-header__seal {
    width: 44px;
    height: 44px;
  }
  
  .twd-header__seal svg {
    width: 22px;
    height: 22px;
  }
}

