script:
/* Noto Kufi Arabic is loaded once from taq_it/public/js/global.js and taq-font.css. */
(function () {
  "use strict";

  var host = typeof root_element !== "undefined" && root_element ? root_element : document;
  var dashboard = host.matches && host.matches("[data-waed-dashboard]")
    ? host
    : host.querySelector && host.querySelector("[data-waed-dashboard]");

  if (!dashboard) return;
  if (dashboard.__waedDashboard && dashboard.__waedDashboard.destroy) {
    dashboard.__waedDashboard.destroy();
  }

  var GENDER = "Male";
  var API_METHODS = ["taq_it.api.get_dashboard_stats", "taq_it.taq_it.api.get_dashboard_stats"];
  var REFRESH_INTERVAL = 5 * 60 * 1000;
  var isPreview = dashboard.getAttribute("data-preview") === "true";
  var refreshing = false;
  var timer = null;
  var statusListener = null;
  var clickListener = null;

  var STATUS_GROUPS = {
    new: ["new", "جديد", "طلب جديد", "new application", "draft", "مقدم"],
    scheduled: ["scheduling an appointment", "scheduling", "مجدول", "تحديد موعد", "appointment scheduled", "scheduled", "في انتظار المقابلة"],
    referred: ["referred for the exam", "referred", "محال للاختبار", "محال للامتحان", "exam referral", "محال"],
    passed: ["successful in the written exam", "passed written", "ناجح في التحريري", "اجتاز التحريري", "passed", "ناجح تحريري"],
    approved: ["approved", "معتمد", "تم الاعتماد", "certified", "مقبول نهائي"],
    ongoing: ["ongoing", "مستمر", "متعين", "تعيين", "على رأس العمل", "مباشر", "active"],
    failedwritten: ["failed written", "راسب في التحريري", "لم يجتز التحريري", "failed", "راسب تحريري", "مرفوض"]
  };

  function normalize(value) {
    return String(value || "").trim().toLowerCase().replace(/[\s_-]+/g, " ");
  }

  function categoryFor(status) {
    var normalized = normalize(status);
    var categories = Object.keys(STATUS_GROUPS);
    for (var i = 0; i < categories.length; i++) {
      var category = categories[i];
      var names = STATUS_GROUPS[category];
      for (var j = 0; j < names.length; j++) {
        var candidate = normalize(names[j]);
        if (normalized === candidate || normalized.indexOf(candidate) !== -1) return category;
      }
    }
    return null;
  }

  function asCount(value) {
    var parsed = Number(value);
    return Number.isFinite(parsed) && parsed >= 0 ? Math.floor(parsed) : 0;
  }

  function formatCount(value) {
    return asCount(value).toLocaleString("en-US");
  }

  function setStatus(message) {
    var status = dashboard.querySelector("[data-updated]");
    if (status) status.textContent = message;
  }

  function setError(message) {
    var error = dashboard.querySelector("[data-error]");
    if (!error) return;
    error.textContent = message;
    error.hidden = !message;
  }

  function renderCount(key, value) {
    var node = dashboard.querySelector('[data-count="' + key + '"]');
    if (node) node.textContent = formatCount(value);
  }

  function render(data) {
    var counts = {
      total: asCount(data.total),
      new: 0,
      scheduled: 0,
      referred: 0,
      passed: 0,
      approved: 0,
      ongoing: 0,
      failedwritten: 0,
      exam_groups: asCount(data.exam_groups)
    };

    Object.keys(data.status_counts || {}).forEach(function (status) {
      var category = categoryFor(status);
      if (category) counts[category] += asCount(data.status_counts[status]);
    });

    Object.keys(counts).forEach(function (key) { renderCount(key, counts[key]); });

    var examined = counts.passed + counts.approved + counts.ongoing + counts.failedwritten;
    var rate = examined ? Math.round(((examined - counts.failedwritten) / examined) * 100) : null;
    var rateNode = dashboard.querySelector('[data-count="rate"]');
    var ring = dashboard.querySelector("[data-rate-ring]");
    if (rateNode) rateNode.textContent = rate === null ? "—" : rate + "%";
    if (ring) {
      ring.style.setProperty("--rate", (rate || 0) + "%");
      var ringValue = ring.querySelector("span");
      if (ringValue) ringValue.textContent = rate === null ? "—" : rate + "%";
    }

    var alert = dashboard.querySelector("[data-alert]");
    var alertCount = dashboard.querySelector("[data-alert-count]");
    if (alert) alert.hidden = counts.new < 1;
    if (alertCount) alertCount.textContent = formatCount(counts.new);

    var stamp = new Date().toLocaleTimeString("ar-LY", { hour: "2-digit", minute: "2-digit" });
    setStatus("آخر تحديث " + stamp);
    setError("");
  }

  function getDashboardStats(methodIndex) {
    if (!window.frappe || typeof frappe.call !== "function") {
      return Promise.reject(new Error("تعذر الوصول إلى واجهة Frappe."));
    }

    var method = API_METHODS[methodIndex];
    return frappe.call({ method: method, args: { gender: GENDER } }).then(function (response) {
      var data = response && response.message;
      if (data && data.success === true) return data;
      throw new Error("لم تُرجع خدمة المؤشرات بيانات صالحة.");
    }).catch(function (error) {
      if (methodIndex + 1 < API_METHODS.length) return getDashboardStats(methodIndex + 1);
      throw error;
    });
  }

  function setRefreshing(value) {
    refreshing = value;
    var button = dashboard.querySelector("[data-refresh]");
    if (button) {
      button.disabled = value;
      if (value) button.setAttribute("aria-busy", "true");
      else button.removeAttribute("aria-busy");
    }
  }

  function refresh(manual) {
    if (refreshing) return Promise.resolve();
    setRefreshing(true);
    setError("");
    if (manual) setStatus("جارٍ تحديث المؤشرات…");
    return getDashboardStats(0).then(render).catch(function (error) {
      console.error("[Waed dashboard] Could not load dashboard stats:", error);
      setStatus("تعذر تحديث البيانات");
      setError("تعذر تحميل المؤشرات. تحقق من صلاحية الوصول إلى طريقة taq_it.api.get_dashboard_stats ثم أعد المحاولة.");
      dashboard.querySelectorAll("[data-count]").forEach(function (node) {
        if (node.querySelector(".wd-skeleton")) node.textContent = "—";
      });
    }).finally(function () {
      setRefreshing(false);
    });
  }

  function openTarget(target) {
    var doctype = target.getAttribute("data-doctype");
    if (["waed_info", "exam_group_date"].indexOf(doctype) === -1) return;

    if (isPreview) {
      setStatus("هذه معاينة ببيانات توضيحية؛ افتح اللوحة داخل ERPNext لعرض السجلات.");
      return;
    }

    if (target.getAttribute("data-action") === "new") {
      if (window.frappe && typeof frappe.new_doc === "function") frappe.new_doc(doctype);
      else window.location.href = "/app/" + doctype.toLowerCase().replace(/_/g, "-") + "/new";
      return;
    }

    var filters = {};
    try { filters = JSON.parse(target.getAttribute("data-filters") || "{}"); } catch (error) { filters = {}; }

    if (window.frappe && typeof frappe.set_route === "function") {
      if (window.TaqWorkspaceGlobal && window.TaqWorkspaceGlobal.setListRoute(doctype, filters)) return;
      frappe.route_options = filters;
      frappe.set_route("List", doctype);
    } else {
      var query = new URLSearchParams(filters).toString();
      window.location.href = "/app/" + doctype.toLowerCase().replace(/_/g, "-") + (query ? "?" + query : "");
    }
  }

  clickListener = function (event) {
    var refreshButton = event.target.closest && event.target.closest("[data-refresh]");
    if (refreshButton && dashboard.contains(refreshButton)) {
      event.preventDefault();
      if (isPreview) {
        setStatus("تم تحديث بيانات المعاينة التوضيحية.");
        return;
      }
      refresh(true);
      return;
    }

    var target = event.target.closest && event.target.closest("[data-doctype]");
    if (target && dashboard.contains(target)) {
      event.preventDefault();
      openTarget(target);
    }
  };
  dashboard.addEventListener("click", clickListener);

  function stopTimer() {
    if (timer) window.clearInterval(timer);
    timer = null;
  }

  function startTimer() {
    stopTimer();
    timer = window.setInterval(function () {
      if (document.visibilityState === "visible") refresh(false);
    }, REFRESH_INTERVAL);
  }

  statusListener = function () {
    if (document.visibilityState === "visible") {
      refresh(false);
      startTimer();
    } else stopTimer();
  };
  document.addEventListener("visibilitychange", statusListener);

  dashboard.__waedDashboard = {
    destroy: function () {
      stopTimer();
      if (clickListener) dashboard.removeEventListener("click", clickListener);
      if (statusListener) document.removeEventListener("visibilitychange", statusListener);
    }
  };

  if (isPreview) {
    render({
      total: 300,
      exam_groups: 8,
      status_counts: {
        New: 194,
        "Scheduling an appointment": 20,
        "referred for the exam": 15,
        "Successful in the written exam": 25,
        Approved: 30,
        Ongoing: 10,
        "Failed Written": 6
      }
    });
  } else {
    refresh(false);
    startTimer();
  }
})();

/* ============================================================
   dashboard.js - لوحة "قسم الوعاظ"
   Frappe v15 Workspace - Custom HTML Block
   ------------------------------------------------------------
   يعتمد على `root_element` المتاح تلقائيًا داخل الـ Custom
   HTML Block في Frappe. لا تغيير في المنطق أو الفلاتر الأصلية،
   فقط إعادة تنظيم وإزالة التكرار وإضافة معالجة الأخطاء.
   ============================================================ */

(function () {
  "use strict";

  /* ---------------------------------------------------------
     أدوات مساعدة عامة (Helpers)
     --------------------------------------------------------- */

  /** يعبّئ قيمة رقمية داخل بطاقة إحصاء ويزيل حالة التحميل */
  function setNum(sel, value) {
    var el = root_element.querySelector(sel + " .tq-count-value");
    if (!el) return;
    el.classList.remove("is-loading");
    el.textContent = typeof value === "number" ? value.toLocaleString("ar") : "0";
  }

  /** يعرض قيمة "—" (تعذّر التحميل) بدل ترك الرقم عالقًا عند فشل الطلب */
  function setNumError(sel) {
    var el = root_element.querySelector(sel + " .tq-count-value");
    if (!el) return;
    el.classList.remove("is-loading");
    el.textContent = "—";
  }

  /** دالة تنقّل موحّدة: تمنع السلوك الافتراضي للرابط وتستخدم راوتر Frappe الداخلي */
  function bindRoute(sel, doctype, filters) {
    var el = root_element.querySelector(sel);
    if (!el) return;
    el.addEventListener("click", function (e) {
      e.preventDefault();
      if (doctype) {
        frappe.set_route("list", doctype, filters || {});
      } else {
        frappe.set_route(el.getAttribute("href").replace(/^\/app\//, ""));
      }
    });
  }

  /** يُظهر/يُخفي صندوق التنبيهات الرئيسي حسب وجود تنبيهات ظاهرة فعليًا */
  function checkAlertsBoxVisibility() {
    var box = root_element.querySelector("#tq-alerts-box");
    if (!box) return;
    var visibleAlerts = box.querySelectorAll('.tq-alert-item:not([style*="display: none"])');
    box.style.display = visibleAlerts.length > 0 ? "block" : "none";
  }

  /** يهيئ عنصر تنبيه: يعبّئ العدّاد، يُظهره، ويربط حدث النقر بمساره الخاص */
  function activateAlert(sel, count, doctype, filters) {
    var alertItem = root_element.querySelector(sel);
    if (!alertItem || !(count > 0)) return;

    var countEl = alertItem.querySelector(".tq-alert-count");
    if (countEl) countEl.textContent = count.toLocaleString("ar");

    alertItem.style.display = "flex";
    alertItem.addEventListener("click", function (e) {
      e.preventDefault();
      frappe.set_route("list", doctype, filters || {});
    });

    checkAlertsBoxVisibility();
  }

  /* ---------------------------------------------------------
     قسم الوعاظ: بطاقات الإحصاء + تنبيه الوعاظ الجدد
     --------------------------------------------------------- */

  frappe.db
    .count("waed_info", { filters: { waed_status: "New" } })
    .then(function (count) {
      setNum("#stat-waed-new", count);
      activateAlert("#alert-new-waed", count, "waed_info", { waed_status: "New" });
    })
    .catch(function () {
      setNumError("#stat-waed-new");
    });

  frappe.db
    .count("waed_info", { filters: { waed_status: "referred for the exam" } })
    .then(function (count) {
      setNum("#stat-waed-referred", count);
    })
    .catch(function () {
      setNumError("#stat-waed-referred");
    });

  frappe.db
    .count("exam_group_date")
    .then(function (count) {
      setNum("#stat-exam-groups", count);
    })
    .catch(function () {
      setNumError("#stat-exam-groups");
    });

  /* ---------------------------------------------------------
     قسم الامتحانات: بطاقات الإحصاء + تنبيه الامتحانات الجارية
     --------------------------------------------------------- */

  frappe.db
    .count("exam_group_date", { filters: { exam_status: "Scheduled" } })
    .then(function (count) {
      setNum("#stat-exam-scheduled", count);
    })
    .catch(function () {
      setNumError("#stat-exam-scheduled");
    });

  // "قيد الإجراء" تجمع حالتين: التحريري والشفوي
  var IN_PROGRESS_FILTER = { exam_status: ["in", ["Written In Progress", "Oral In Progress"]] };

  frappe.db
    .count("exam_group_date", { filters: IN_PROGRESS_FILTER })
    .then(function (count) {
      setNum("#stat-exam-inprogress", count);
      activateAlert("#alert-exam-progress", count, "exam_group_date", IN_PROGRESS_FILTER);
    })
    .catch(function () {
      setNumError("#stat-exam-inprogress");
    });

  frappe.db
    .count("exam_group_date", { filters: { exam_status: "Completed" } })
    .then(function (count) {
      setNum("#stat-exam-completed", count);
    })
    .catch(function () {
      setNumError("#stat-exam-completed");
    });

  /* ---------------------------------------------------------
     تنبيه أقرب موعد امتحان قادم
     --------------------------------------------------------- */

  function formatRemainingDays(daysDiff) {
    if (daysDiff === 0) return "اليوم";
    if (daysDiff === 1) return "غداً";
    if (daysDiff === 2) return "بعد غد";
    if (daysDiff <= 10) return "متبقي " + daysDiff.toLocaleString("ar") + " أيام";

    var months = Math.floor(daysDiff / 30);
    var remDays = daysDiff % 30;

    if (months > 0) {
      var text = "متبقي " + months.toLocaleString("ar") + " شهر";
      if (remDays > 0) text += " و " + remDays.toLocaleString("ar") + " يوم";
      return text;
    }
    return "متبقي " + daysDiff.toLocaleString("ar") + " يوم";
  }

  frappe.model
    .with_doctype("exam_group_date", function () {
      var meta = frappe.get_meta("exam_group_date");
      var dateField = "date";

      if (meta && meta.fields) {
        var found = meta.fields.find(function (f) {
          return f.fieldtype === "Date";
        });
        if (found) dateField = found.fieldname;
      }

      frappe.db
        .get_list("exam_group_date", {
          filters: { exam_status: "Scheduled" },
          fields: ["name", dateField],
          order_by: dateField + " asc",
          limit: 1
        })
        .then(function (records) {
          if (!records || !records.length || !records[0][dateField]) return;

          var examDate = new Date(records[0][dateField]);
          var today = new Date();
          today.setHours(0, 0, 0, 0);
          examDate.setHours(0, 0, 0, 0);

          var daysDiff = Math.ceil((examDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
          if (daysDiff < 0) return;

          var alertItem = root_element.querySelector("#alert-next-exam");
          if (!alertItem) return;

          var dateOptions = { year: "numeric", month: "long", day: "numeric" };
          alertItem.querySelector(".tq-alert-date").textContent = examDate.toLocaleDateString("ar-LY", dateOptions);
          alertItem.querySelector(".tq-alert-remaining").textContent = formatRemainingDays(daysDiff);
          alertItem.style.display = "flex";

          alertItem.addEventListener("click", function (e) {
            e.preventDefault();
            frappe.set_route("list", "exam_group_date", { exam_status: "Scheduled" });
          });

          checkAlertsBoxVisibility();
        })
        .catch(function () {
          /* تعذّر تحديد أقرب موعد امتحان - لا تنبيه يُعرض في هذه الحالة */
        });
    })
    .catch(function () {
      /* تعذّر تحميل تعريف نوع المستند exam_group_date */
    });

  /* ---------------------------------------------------------
     ربط التنقّل لكل بطاقات الإحصاء وأدوات الاختصارات
     --------------------------------------------------------- */

  // بطاقات الإحصاء
  bindRoute("#stat-waed-new", "waed_info", { waed_status: "New" });
  bindRoute("#stat-waed-referred", "waed_info", { waed_status: "referred for the exam" });
  bindRoute("#stat-exam-groups", "exam_group_date");
  bindRoute("#stat-exam-scheduled", "exam_group_date", { exam_status: "Scheduled" });
  bindRoute("#stat-exam-inprogress", "exam_group_date", IN_PROGRESS_FILTER);
  bindRoute("#stat-exam-completed", "exam_group_date", { exam_status: "Completed" });

  // أدوات الوعاظ
  bindRoute("#link-waed-new", "waed_info", { waed_status: "New" });
  bindRoute("#link-waed-scheduled", "waed_info", { waed_status: "Scheduling an appointment" });
  bindRoute("#link-waed-exam-set", "waed_info", { waed_status: "referred for the exam" });
  bindRoute("#link-waed-passed", "waed_info", { waed_status: "Successful in the written exam" });
  bindRoute("#link-waed-failed", "waed_info", { waed_status: "Rejected" });
  bindRoute("#link-waed-approved", "waed_info", { waed_status: "Approved" });

  // أدوات الامتحانات (تنقّل إلى مسار مباشر بدل قائمة مفلترة)
  bindRoute("#link-exam-create");
  bindRoute("#link-exam-date-create");
  bindRoute("#link-exam-grading");
  bindRoute("#link-exam-approve");
})();

style:
@import url('https://fonts.googleapis.com/css2?family=Tajawal:wght@400;500;700;800;900&display=swap');

/*
  ============================================================
  dashboard.css — لوحة "قسم الوعاظ وقسم الامتحانات"
  Frappe v15 Workspace - Custom HTML Block
  ------------------------------------------------------------
  إعادة تصميم بصري كامل (تنسيق فقط) — بلا أي تغيير في المنطق
  أو الأسماء أو المعرّفات التي يعتمد عليها dashboard.js.
  هوية اللون: أخضر زمردي عميق + ذهبي هادئ، بنمط SaaS/ERP حديث
  مع لمسات هندسية إسلامية خفيفة.
  ============================================================
*/

/* ============================================================
   1) نظام التصميم (Design Tokens)
   ============================================================ */
.tq-dash {
  /* أسطح محايدة دافئة */
  --tq-bg:            #fdfcfa;
  --tq-surface:       #ffffff;
  --tq-surface-alt:   #f6f8f7;
  --tq-border:        #e3e9e6;
  --tq-border-soft:   #edf2f0;

  /* حبر النص */
  --tq-ink:           #0e2a22;
  --tq-ink-soft:      #55655d;
  --tq-ink-faint:     #8d9c94;

  /* الأخضر الزمردي (اللون الأساسي) */
  --tq-accent:        #0d5445;
  --tq-accent-dark:   #082e26;
  --tq-accent-light:  #17795f;
  --tq-accent-soft:   #e5f3ee;
  --tq-accent-ring:   rgba(13, 84, 69, .15);

  /* الذهبي (لون ثانوي / تمييز) */
  --tq-gold:          #ad8a3f;
  --tq-gold-light:    #cba85e;
  --tq-gold-soft:     #faf5e7;
  --tq-gold-ring:     rgba(173, 138, 63, .16);

  --tq-emerald:       #1c8467;
  --tq-emerald-soft:  #e8f7f0;

  --tq-amber:         #a8720c;
  --tq-amber-soft:    #fcf1de;

  --tq-red:           #ad3f3f;
  --tq-red-soft:      #fbecec;

  --tq-grey:          #57616d;
  --tq-grey-soft:     #edf0f3;

  /* الهيدر (Hero) الداكن */
  --tq-hero-1:        #082019;
  --tq-hero-2:        #0d5445;
  --tq-hero-3:        #114a3d;
  --tq-cream:         #f5ebd7;
  --tq-cream-soft:    #bfdcd0;

  /* مقاييس موحّدة */
  --tq-radius-sm: 10px;
  --tq-radius-md: 14px;
  --tq-radius-lg: 20px;
  --tq-radius-xl: 26px;

  --tq-space-1: 6px;
  --tq-space-2: 10px;
  --tq-space-3: 16px;
  --tq-space-4: 24px;
  --tq-space-5: 36px;

  --tq-shadow-xs: 0 1px 2px rgba(8, 32, 25, .05);
  --tq-shadow-sm: 0 2px 8px rgba(8, 32, 25, .06);
  --tq-shadow-md: 0 10px 26px -6px rgba(8, 32, 25, .14);
  --tq-shadow-lg: 0 24px 48px -14px rgba(8, 32, 25, .22);

  --tq-ease: cubic-bezier(.22, 1, .36, 1);
  --tq-ease-soft: cubic-bezier(.4, 0, .2, 1);
  --tq-font: "Tajawal", "Segoe UI", "Cairo", "Geeza Pro", Arial, sans-serif;

  display: block;
  box-sizing: border-box;
  font-family: var(--tq-font);
  color: var(--tq-ink);
  background: var(--tq-bg);
  direction: rtl;
  text-align: right;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

.tq-dash *,
.tq-dash *::before,
.tq-dash *::after {
  box-sizing: border-box;
}

.tq-dash ul {
  list-style: none;
  margin: 0;
  padding: 0;
}

.tq-dash a {
  text-decoration: none;
  color: inherit;
}

.tq-dash :focus-visible {
  outline: 2px solid var(--tq-accent);
  outline-offset: 2px;
  border-radius: var(--tq-radius-sm);
}

@media (prefers-reduced-motion: reduce) {
  .tq-dash * { transition: none !important; animation: none !important; }
}

/* ============================================================
   2) الهيدر الرئيسي (Hero)
   ============================================================ */
.tq-hero {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-radius: var(--tq-radius-xl);
  padding: 46px 48px;
  margin-bottom: var(--tq-space-5);
  background:
    radial-gradient(120% 160% at 100% 0%, rgba(203, 168, 94, .16) 0%, transparent 45%),
    linear-gradient(120deg, var(--tq-hero-1) 0%, var(--tq-hero-2) 52%, var(--tq-hero-3) 100%);
  border: 1px solid rgba(203, 168, 94, .22);
  box-shadow: var(--tq-shadow-lg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--tq-space-4);
  color: var(--tq-cream);
}

/* نمط زخرفي هندسي خفيف مستوحى من الطراز الإسلامي */
.tq-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  opacity: .5;
  background-image:
    repeating-linear-gradient(45deg, rgba(203, 168, 94, .07) 0, rgba(203, 168, 94, .07) 1px, transparent 1px, transparent 30px),
    repeating-linear-gradient(-45deg, rgba(203, 168, 94, .07) 0, rgba(203, 168, 94, .07) 1px, transparent 1px, transparent 30px);
  -webkit-mask-image: linear-gradient(to left, black, transparent 75%);
          mask-image: linear-gradient(to left, black, transparent 75%);
}

.tq-hero::after {
  content: "";
  position: absolute;
  width: 260px;
  height: 260px;
  left: -80px;
  top: -90px;
  border: 1.5px solid rgba(203, 168, 94, .28);
  border-radius: 50%;
  pointer-events: none;
}

.tq-hero__content {
  position: relative;
  z-index: 1;
  max-width: 640px;
}

.tq-hero__eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .4px;
  color: var(--tq-gold-light);
  background: rgba(203, 168, 94, .1);
  border: 1px solid rgba(203, 168, 94, .38);
  padding: 6px 15px;
  border-radius: 999px;
  margin-bottom: 16px;
}

.tq-hero__eyebrow::before {
  content: "◆";
  font-size: 8px;
}

.tq-hero__title {
  font-size: 30px;
  font-weight: 900;
  letter-spacing: -.2px;
  color: var(--tq-cream);
  margin: 0 0 10px 0;
}

.tq-hero__subtitle {
  font-size: 14px;
  color: var(--tq-cream-soft);
  margin: 0;
  max-width: 540px;
  opacity: .92;
  line-height: 1.9;
}

.tq-hero__seal {
  position: relative;
  z-index: 1;
  flex-shrink: 0;
  width: 90px;
  height: 90px;
  border-radius: 50%;
  background: rgba(255, 255, 255, .05);
  border: 1px solid rgba(203, 168, 94, .4);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: inset 0 0 0 1px rgba(203, 168, 94, .1), var(--tq-shadow-sm);
}

.tq-hero__seal svg {
  width: 42px;
  height: 42px;
  color: var(--tq-gold-light);
}

/* ============================================================
   3) نظام التنبيهات الذكي
   ============================================================ */
.tq-alerts-container {
  display: flex;
  flex-direction: column;
  gap: var(--tq-space-2);
  margin-bottom: var(--tq-space-4);
  animation: tqFadeInUp .45s var(--tq-ease);
}

.tq-alert-item {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 15px 20px 15px 22px;
  border-radius: var(--tq-radius-md);
  font-size: 13.5px;
  font-weight: 600;
  background: var(--tq-surface);
  border: 1px solid var(--tq-border-soft);
  box-shadow: var(--tq-shadow-xs);
  transition: transform .2s var(--tq-ease), box-shadow .2s var(--tq-ease), border-color .2s var(--tq-ease);
  cursor: pointer;
  overflow: hidden;
}

.tq-alert-item::before {
  content: "";
  position: absolute;
  inset-inline-start: 0;
  top: 0;
  bottom: 0;
  width: 4px;
  background: var(--tq-alert-accent, var(--tq-accent));
}

.tq-alert-content-wrapper {
  display: flex;
  align-items: center;
  gap: 14px;
}

.tq-alert-icon {
  font-size: 16px;
  flex-shrink: 0;
  width: 34px;
  height: 34px;
  border-radius: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--tq-alert-soft, var(--tq-accent-soft));
}

.tq-alert-text {
  color: var(--tq-ink);
  line-height: 1.5;
}

.tq-alert-text strong {
  font-weight: 800;
  color: var(--tq-alert-accent, var(--tq-accent));
  background: var(--tq-alert-soft, var(--tq-accent-soft));
  padding: 2px 8px;
  border-radius: 6px;
  margin: 0 4px;
}

.tq-alert-arrow {
  font-size: 15px;
  color: var(--tq-ink-faint);
  opacity: .6;
  transition: transform .2s var(--tq-ease), opacity .2s var(--tq-ease), color .2s var(--tq-ease);
}

.tq-alert-item:hover {
  transform: translateY(-2px);
  box-shadow: var(--tq-shadow-md);
  border-color: var(--tq-border);
}

.tq-alert-item:hover .tq-alert-arrow {
  opacity: 1;
  color: var(--tq-alert-accent, var(--tq-accent));
  transform: translateX(-4px);
}

.tq-alert-item:active {
  transform: translateY(0);
}

.tq-alert-item--blue  { --tq-alert-accent: var(--tq-accent);  --tq-alert-soft: var(--tq-accent-soft); }
.tq-alert-item--amber { --tq-alert-accent: var(--tq-amber);   --tq-alert-soft: var(--tq-amber-soft); }
.tq-alert-item--gold  { --tq-alert-accent: var(--tq-gold);    --tq-alert-soft: var(--tq-gold-soft); }

@keyframes tqFadeInUp {
  from { opacity: 0; transform: translateY(10px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ============================================================
   4) عناوين الأقسام الرئيسية (Modules)
   ============================================================ */
.tq-module {
  margin-bottom: var(--tq-space-5);
}

.tq-module__header {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: var(--tq-space-4);
  padding-bottom: var(--tq-space-3);
  border-bottom: 1px solid var(--tq-border-soft);
}

.tq-module__icon {
  flex-shrink: 0;
  width: 42px;
  height: 42px;
  border-radius: 13px;
  background: linear-gradient(155deg, var(--tq-accent-soft), #ffffff);
  border: 1px solid var(--tq-border-soft);
  color: var(--tq-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--tq-shadow-xs);
}

.tq-module__icon svg {
  width: 21px;
  height: 21px;
}

.tq-module__title {
  font-size: 19.5px;
  font-weight: 800;
  color: var(--tq-ink);
  margin: 0;
  letter-spacing: -.1px;
}

.tq-module__subtitle {
  font-size: 12.5px;
  color: var(--tq-ink-faint);
  margin: 3px 0 0 0;
}

.tq-subsection {
  margin-bottom: var(--tq-space-4);
}

.tq-subsection:last-child {
  margin-bottom: 0;
}

.tq-subsection-title {
  font-size: 13.5px;
  font-weight: 700;
  color: var(--tq-ink-soft);
  margin: 0 0 var(--tq-space-3) 0;
  display: flex;
  align-items: center;
  gap: 9px;
  text-transform: uppercase;
  letter-spacing: .3px;
}

.tq-subsection-title::before {
  content: "";
  width: 4px;
  height: 14px;
  border-radius: 3px;
  background: linear-gradient(180deg, var(--tq-gold-light), var(--tq-gold));
  display: inline-block;
}

/* ============================================================
   5) بطاقات الإحصاء (Stat Cards)
   ============================================================ */
.tq-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--tq-space-3);
  margin-bottom: var(--tq-space-4);
}

.tq-stat-card {
  position: relative;
  display: block;
  background: var(--tq-surface);
  border: 1px solid var(--tq-border-soft);
  border-radius: var(--tq-radius-lg);
  padding: 20px 22px;
  box-shadow: var(--tq-shadow-xs);
  overflow: hidden;
  transition: transform .2s var(--tq-ease), box-shadow .2s var(--tq-ease), border-color .2s var(--tq-ease);
}

.tq-stat-card::after {
  content: "";
  position: absolute;
  inset-inline-end: -30px;
  top: -30px;
  width: 100px;
  height: 100px;
  border-radius: 50%;
  background: var(--tq-card-accent, var(--tq-accent));
  opacity: .07;
  transition: opacity .2s var(--tq-ease), transform .3s var(--tq-ease);
}

.tq-stat-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--tq-shadow-md);
  border-color: color-mix(in srgb, var(--tq-card-accent, var(--tq-accent)) 30%, var(--tq-border));
}

.tq-stat-card:hover::after {
  opacity: .12;
  transform: scale(1.15);
}

.tq-stat-card--blue    { --tq-card-accent: var(--tq-accent); }
.tq-stat-card--gold    { --tq-card-accent: var(--tq-gold); }
.tq-stat-card--emerald { --tq-card-accent: var(--tq-emerald); }
.tq-stat-card--amber   { --tq-card-accent: var(--tq-amber); }
.tq-stat-card--grey    { --tq-card-accent: var(--tq-grey); }

.tq-stat-card__top {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}

.tq-stat-card__icon {
  width: 38px;
  height: 38px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: color-mix(in srgb, var(--tq-card-accent) 12%, white);
  color: var(--tq-card-accent);
}

.tq-stat-card__icon svg {
  width: 18px;
  height: 18px;
}

.tq-stat-card__value {
  position: relative;
  z-index: 1;
  display: block;
  font-size: 27px;
  font-weight: 800;
  color: var(--tq-ink);
  line-height: 1;
  margin-bottom: 6px;
  font-variant-numeric: tabular-nums;
  transition: color .2s var(--tq-ease-soft);
}

.tq-stat-card__value.is-loading {
  color: var(--tq-ink-faint);
}

.tq-stat-card__label {
  position: relative;
  z-index: 1;
  display: block;
  font-size: 12.5px;
  color: var(--tq-ink-soft);
  font-weight: 600;
}

/* ============================================================
   6) بطاقات الأدوات / الاختصارات (Actions)
   ============================================================ */
.tq-actions__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--tq-space-2);
}

.tq-actions__grid--3 {
  grid-template-columns: repeat(3, 1fr);
}

.tq-action {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  text-align: center;
  background: var(--tq-surface);
  border: 1px solid var(--tq-border-soft);
  border-radius: var(--tq-radius-md);
  padding: 18px 12px;
  cursor: pointer;
  transition: border-color .18s var(--tq-ease), box-shadow .18s var(--tq-ease), transform .18s var(--tq-ease), background .18s var(--tq-ease);
}

.tq-action:hover {
  border-color: transparent;
  box-shadow: 0 0 0 1.5px var(--tq-action-color, var(--tq-accent)) inset, var(--tq-shadow-md);
  background: var(--tq-action-soft, var(--tq-accent-soft));
  transform: translateY(-3px);
}

.tq-action__icon {
  width: 38px;
  height: 38px;
  border-radius: 12px;
  background: var(--tq-action-soft, var(--tq-accent-soft));
  color: var(--tq-action-color, var(--tq-accent));
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform .18s var(--tq-ease);
}

.tq-action:hover .tq-action__icon {
  transform: scale(1.08);
  background: var(--tq-surface);
}

.tq-action__icon svg {
  width: 19px;
  height: 19px;
}

.tq-action__label {
  font-size: 12.5px;
  font-weight: 700;
  color: var(--tq-ink);
  line-height: 1.4;
}

.tq-action--green  { --tq-action-color: var(--tq-emerald); --tq-action-soft: var(--tq-emerald-soft); }
.tq-action--orange { --tq-action-color: var(--tq-amber);   --tq-action-soft: var(--tq-amber-soft); }
.tq-action--yellow,
.tq-action--gold   { --tq-action-color: var(--tq-gold);    --tq-action-soft: var(--tq-gold-soft); }
.tq-action--red    { --tq-action-color: var(--tq-red);     --tq-action-soft: var(--tq-red-soft); }
.tq-action--blue   { --tq-action-color: var(--tq-accent);  --tq-action-soft: var(--tq-accent-soft); }
.tq-action--grey   { --tq-action-color: var(--tq-grey);    --tq-action-soft: var(--tq-grey-soft); }

/* ============================================================
   7) الاستجابة (Responsive)
   ============================================================ */
@media (max-width: 1100px) {
  .tq-actions__grid,
  .tq-actions__grid--3 {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 900px) {
  .tq-stats {
    grid-template-columns: repeat(2, 1fr);
  }
  .tq-hero {
    padding: 36px 34px;
  }
}

@media (max-width: 640px) {
  .tq-hero {
    flex-direction: column-reverse;
    align-items: flex-start;
    padding: 28px 22px;
    border-radius: var(--tq-radius-lg);
  }
  .tq-hero__seal {
    width: 60px;
    height: 60px;
  }
  .tq-hero__seal svg {
    width: 28px;
    height: 28px;
  }
  .tq-hero__title {
    font-size: 22px;
  }
  .tq-stats {
    grid-template-columns: 1fr;
  }
  .tq-actions__grid,
  .tq-actions__grid--3 {
    grid-template-columns: repeat(2, 1fr);
  }
  .tq-module__title {
    font-size: 17px;
  }
  .tq-alert-item {
    flex-direction: column;
    align-items: flex-start;
    gap: 10px;
    padding: 16px 18px;
  }
  .tq-alert-arrow {
    display: none;
  }
}

@media (max-width: 400px) {
  .tq-actions__grid,
  .tq-actions__grid--3 {
    grid-template-columns: 1fr;
  }
  .tq-hero {
    padding: 24px 18px;
  }
  .tq-hero__title {
    font-size: 20px;
  }
}

script:
/* Noto Kufi Arabic is loaded once from taq_it/public/js/global.js and taq-font.css. */
(function () {
  "use strict";

  /* ==========================================================================
   * لوحة قسم الواعظات - Modular Executive Engine (Frappe Custom Block)
   * المميزات المتقدمة:
   * 1. الأداء الفائق: تجميع الاستعلامات في طلب واحد (Single Aggregated Query / GROUP BY)
   * 2. مرونة الفلاتر: مطابقة الحالات ديناميكياً بدون ترميز ثابت هش (Fuzzy Status Matcher)
   * 3. التحميل اللحظي: Stale-While-Revalidate عبر sessionStorage بدون شاشات انتظار
   * 4. التحديث التلقائي الذكي: Polling دوري مع إدارة دورة حياة التبويب (Page Visibility API)
   * ========================================================================== */

  var root = typeof root_element !== "undefined" ? root_element : document.querySelector(".waed-dash") || document;

  // تنظيف أي مؤقتات قديمة عند إعادة تحميل الـ Workspace
  if (root.__femalwaed_poller) {
    root.__femalwaed_poller.stop();
  }

  installNumberTypography(root);

  function installNumberTypography(scope) {
    if (window.TaqWorkspaceGlobal && window.TaqWorkspaceGlobal.installNumberTypography) {
      window.TaqWorkspaceGlobal.installNumberTypography(scope);
    }
  }

  // 1. الإعدادات والثوابت (Configuration)
  var CONFIG = {
