    hasCachedData: false,
    counts: {
      total: 0,
      new: 0,
      scheduled: 0,
      referred: 0,
      passed: 0,
      approved: 0,
      ongoing: 0,
      failedwritten: 0,
      exam_groups: 0
    }
  };

