            STATE.nextExamDate = data.counts.next_exam_date;
          }
          STATE.hasCachedData = true;
          return true;
        }
      } catch (e) {
        console.warn("[Exam Dashboard] Cache read skipped:", e);
      }
      return false;
    },
    saveState: function () {
      try {
        sessionStorage.setItem(CONFIG.CACHE_KEY, JSON.stringify({
          counts: STATE.counts,
          timestamp: Date.now()
        }));
      } catch (e) {}
    }
  };

  // 6. منطق العرض وتحديث الواجهة (UI Presenter)
  var UIPresenter = {
    formatDigits: function (val) {
      if (val === null || val === undefined) return "0";
      return String(val).replace(/[٠-٩]/g, function (d) {
        return d.charCodeAt(0) - 1632;
      });
    },

    parseDateSafe: function (dateStr) {
      if (!dateStr) return null;
      if (dateStr instanceof Date) return isNaN(dateStr.getTime()) ? null : dateStr;
      var s = String(dateStr).trim().split(" ")[0];
      var parts = s.split(/[-/]/);
      if (parts.length === 3) {
        if (parts[0].length === 4) {
          return new Date(parseInt(parts[0], 10), parseInt(parts[1], 10) - 1, parseInt(parts[2], 10));
        }
        if (parts[2].length === 4) {
          return new Date(parseInt(parts[2], 10), parseInt(parts[1], 10) - 1, parseInt(parts[0], 10));
        }
      }
      var d = new Date(dateStr);
      return isNaN(d.getTime()) ? null : d;
    },

    animateNumber: function (el, targetValue, isInstant) {
      if (!el) return;
      el.classList.remove("is-loading");
      el.setAttribute("dir", "ltr");
      el.setAttribute("lang", "en");

      if (typeof targetValue !== "number" || isNaN(targetValue)) {
        el.textContent = "0";
        return;
      }

      if (isInstant) {
        el.textContent = UIPresenter.formatDigits(targetValue);
        return;
      }

      var currentNum = parseInt(el.textContent.replace(/[^0-9]/g, ""), 10) || 0;
      var startValue = currentNum;
      var startTime = null;
      var animDuration = CONFIG.ANIMATION_DURATION_MS;

      function step(timestamp) {
        if (!startTime) startTime = timestamp;
        var progress = Math.min((timestamp - startTime) / animDuration, 1);
        var easeProgress = 1 - Math.pow(1 - progress, 3);
        var current = Math.round(startValue + (targetValue - startValue) * easeProgress);

        el.textContent = UIPresenter.formatDigits(current);

        if (progress < 1) {
          window.requestAnimationFrame(step);
        } else {
          el.textContent = UIPresenter.formatDigits(targetValue);
        }
      }

      window.requestAnimationFrame(step);
    },

    setCount: function (selector, value, isInstant) {
      var targetEl = root.querySelector(selector);
      if (!targetEl) return;
      var numEl = targetEl.querySelector(".tq-count-value") || targetEl;
      UIPresenter.animateNumber(numEl, typeof value === "number" ? value : 0, isInstant);
    },

    setText: function (selector, text) {
      var targetEl = root.querySelector(selector);
      if (!targetEl) return;
      var numEl = targetEl.querySelector(".tq-count-value") || targetEl;
      numEl.classList.remove("is-loading");
      numEl.setAttribute("dir", "ltr");
      numEl.setAttribute("lang", "en");
      numEl.textContent = UIPresenter.formatDigits(text);
      var rateRing = targetEl.querySelector("[data-rate-ring]");
      if (rateRing) {
        var percentage = parseFloat(String(text).replace("%", ""));
        rateRing.style.setProperty("--rate", (isNaN(percentage) ? 0 : Math.max(0, Math.min(100, percentage))) + "%");
      }
    },

    setError: function (selector) {
      var targetEl = root.querySelector(selector);
      if (!targetEl) return;
      var numEl = targetEl.querySelector(".tq-count-value") || targetEl;
      numEl.classList.remove("is-loading");
      numEl.textContent = "—";
    },

    updateAlertBanner: function (nextExamData) {
      var box = root.querySelector("#twd-exams-alerts-box") || root.querySelector("#twd-exam-alerts-box");
      var alertLive = root.querySelector("#alert-exam-progress");
      var alertNext = root.querySelector("#alert-next-exam");
      if (!box) return;

      var hasLiveAlert = false;
      var hasNextAlert = false;

      // 1. تنبيه الجلسات الجارية
      if (alertLive) {
        var liveCount = (STATE.counts && STATE.counts.inProgress) || 0;
        if (liveCount > 0) {
          var countEl = alertLive.querySelector(".awqaf-alert__count");
          if (countEl) countEl.textContent = UIPresenter.formatDigits(liveCount);
          alertLive.style.display = "flex";
          hasLiveAlert = true;
        } else {
          alertLive.style.display = "none";
        }
      }

      // 2. تنبيه أقرب موعد امتحان قادم
      if (alertNext) {
        var rawDate = (nextExamData && nextExamData.dateStr) || (STATE.counts && STATE.counts.next_exam_date) || STATE.nextExamDate;
        var examDate = UIPresenter.parseDateSafe(rawDate);

        if (examDate) {
          var today = new Date();
          today.setHours(0, 0, 0, 0);
          examDate.setHours(0, 0, 0, 0);

          var daysDiff = Math.round((examDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
          var monthsArr = ["يناير", "فبراير", "مارس", "أبريل", "مايو", "يونيو", "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"];
          var dateEl = alertNext.querySelector(".awqaf-alert__date");
          var remEl = alertNext.querySelector(".awqaf-alert__remaining");

          if (dateEl) {
            dateEl.innerHTML = '<span class="num">' + UIPresenter.formatDigits(examDate.getDate()) + '</span> ' + monthsArr[examDate.getMonth()] + ' <span class="num">' + UIPresenter.formatDigits(examDate.getFullYear()) + '</span>';
          }
          if (remEl) {
            var remText = "";
            if (daysDiff === 0) remText = "اليوم";
            else if (daysDiff === 1) remText = "غداً";
            else if (daysDiff === 2) remText = "بعد غد";
            else if (daysDiff > 2) remText = 'متبقي <span class="num">' + UIPresenter.formatDigits(daysDiff) + '</span> يوم';
            else remText = 'منذ <span class="num">' + UIPresenter.formatDigits(Math.abs(daysDiff)) + '</span> يوم';
            remEl.innerHTML = remText;
          }

          alertNext.style.display = "flex";
          hasNextAlert = true;
        } else {
          alertNext.style.display = "none";
        }
      }

      box.style.display = (hasLiveAlert || hasNextAlert) ? "flex" : "none";
    },

    calculateCompletionRate: function () {
      if (STATE.counts.total > 0) {
        return Math.round((STATE.counts.completed / STATE.counts.total) * 100);
      }
      return null;
    },

    renderAll: function (isInstant) {
      UIPresenter.setCount("#stat-exam-forms", STATE.counts.forms, isInstant);
      UIPresenter.setCount("#stat-exam-total", STATE.counts.total, isInstant);
      UIPresenter.setCount("#stat-exam-scheduled", STATE.counts.scheduled, isInstant);
      UIPresenter.setCount("#stat-exam-written", STATE.counts.written, isInstant);
      UIPresenter.setCount("#stat-exam-oral", STATE.counts.oral, isInstant);
      UIPresenter.setCount("#stat-exam-completed", STATE.counts.completed, isInstant);
      UIPresenter.setCount("#stat-exam-inprogress", STATE.counts.inProgress, isInstant);

      var rate = UIPresenter.calculateCompletionRate();
      if (rate !== null) {
        UIPresenter.setText("#stat-exam-rate", rate + "%");
      } else {
        UIPresenter.setText("#stat-exam-rate", "—");
      }
    },

    setRefreshSpinning: function (isSpinning) {
      var icon = root.querySelector(".ex-icon-refresh");
      if (icon) {
        if (isSpinning) icon.classList.add("is-spinning");
        else icon.classList.remove("is-spinning");
      }
    }
  };

  // 7. موجه التنقل (Router)
  var Router = {
    navigate: function (target) {
      var doctype = target.getAttribute("data-doctype");
      if (!doctype || CONFIG.ALLOWED_DOCTYPES.indexOf(doctype) === -1) return;

      if (target.getAttribute("data-action") === "new") {
        if (window.frappe && frappe.new_doc) {
          frappe.new_doc(doctype);
        } else {
          window.location.href = "/app/" + encodeURIComponent(doctype.toLowerCase().replace(/ /g, "-")) + "/new";
        }
        return;
      }

      var filters = {};
      try {
        var rawFilters = target.getAttribute("data-filters");
        if (rawFilters) filters = JSON.parse(rawFilters);
      } catch (err) {
        filters = {};
      }

      if (window.frappe && frappe.set_route) {
        if (window.TaqWorkspaceGlobal && window.TaqWorkspaceGlobal.setListRoute(doctype, filters)) return;
        frappe.route_options = filters;
        frappe.set_route("list", doctype, filters);
      } else {
        var query = Object.keys(filters).length > 0 ? "?" + new URLSearchParams(filters).toString() : "";
        window.location.href = "/app/" + encodeURIComponent(doctype.toLowerCase().replace(/ /g, "-")) + query;
      }
    }
  };

  // 8. المتحكم الدوري الذكي (Smart Poller)
  var Poller = {
    timer: null,
    start: function () {
      Poller.stop();
      Poller.timer = setInterval(function () {
        if (root.ownerDocument.visibilityState === "visible" && !STATE.isRefreshing) {
          loadDashboardData(false);
        }
      }, CONFIG.POLLING_INTERVAL_MS);
    },
    stop: function () {
      if (Poller.timer) {
        clearInterval(Poller.timer);
        Poller.timer = null;
      }
    }
  };

  root.__exam_poller = Poller;

  // 9. ربط الأحداث (Event Listeners)
  function initEvents() {
    root.addEventListener("click", function (e) {
      var refreshBtn = e.target.closest("#btn-exam-refresh");
      if (refreshBtn) {
        e.preventDefault();
        loadDashboardData(true);
        return;
      }

      var toolBtn = e.target.closest("#link-exam-tool, #link-exam-grading, #link-exam-approve");
      if (toolBtn) {
        e.preventDefault();
        if (window.frappe && frappe.set_route) {
          frappe.route_options = { target_gender: CONFIG.GENDER };
          frappe.set_route("exam_tool");
        } else {
          window.location.href = "/app/exam_tool?target_gender=" + encodeURIComponent(CONFIG.GENDER);
        }
        return;
      }

      var navTarget = e.target.closest("[data-doctype]");
      if (navTarget) {
        e.preventDefault();
        Router.navigate(navTarget);
      }
    });

    root.addEventListener("keydown", function (e) {
      if (e.key === "Enter" || e.key === " ") {
        var target = e.target.closest("[data-doctype], #btn-exam-refresh, #link-exam-tool, #link-exam-grading, #link-exam-approve");
        if (target) {
          e.preventDefault();
          target.click();
        }
      }
    });

    root.ownerDocument.addEventListener("visibilitychange", function () {
      if (root.ownerDocument.visibilityState === "visible") {
        loadDashboardData(false);
        Poller.start();
      } else {
        Poller.stop();
      }
    });
  }

  // 10. دورة تحميل البيانات (Data Lifecycle)
  function loadDashboardData(isManualRefresh) {
    if (STATE.isRefreshing) return;
    STATE.isRefreshing = true;

    if (isManualRefresh) {
      UIPresenter.setRefreshSpinning(true);
    }

    var statsPromise = APIService.fetchAggregatedStats();
    var nextExamPromise = APIService.fetchNextScheduledExam();

    Promise.all([statsPromise, nextExamPromise])
      .then(function (results) {
        var stats = results[0];
        var nextExam = results[1] || (stats && stats.next_exam_date ? { dateStr: stats.next_exam_date } : null);
        STATE.counts = stats;
        CacheManager.saveState();
        UIPresenter.renderAll(false);
        UIPresenter.updateAlertBanner(nextExam);
      })
      .catch(function (err) {
        console.error("[Exam Dashboard] Load error:", err);
        if (!STATE.hasCachedData) {
          [
            "#stat-exam-forms",
            "#stat-exam-total",
            "#stat-exam-scheduled",
            "#stat-exam-written",
            "#stat-exam-oral",
            "#stat-exam-completed",
            "#stat-exam-inprogress",
            "#stat-exam-rate"
          ].forEach(UIPresenter.setError);
        }
      })
      .finally(function () {
        STATE.isRefreshing = false;
        if (isManualRefresh) {
          setTimeout(function () {
            UIPresenter.setRefreshSpinning(false);
          }, 400);
        }
      });
  }

  // 11. الإقلاع الفوري (Bootstrap)
  initEvents();

  var hasCache = CacheManager.loadCachedState();
  if (hasCache) {
    UIPresenter.renderAll(true);
    UIPresenter.updateAlertBanner(null);
  }

  loadDashboardData(false);
  Poller.start();
})();

// ==============================================================
// WAED DASHBOARD - RUNTIME CONTROLLER
// الهيئة العامة للأوقاف والشؤون الإسلامية
// ==============================================================
(function() {
    const scope = (typeof root_element !== 'undefined' && root_element) ? root_element : document;

    const nameEl = scope.querySelector('#waed-employee-name');
    const salutationTimeEl = scope.querySelector('#waed-salutation-time');
    const clockEl = scope.querySelector('#waed-live-clock');
    const gregEl = scope.querySelector('#waed-live-gregorian');
    const hijriEl = scope.querySelector('#waed-live-hijri');

    // حقول بطاقة مواقيت الصلاة
    const prayerDateTimeEl = scope.querySelector('#prayer-datetime-display');
    const prayerHijriEl = scope.querySelector('#prayer-hijri-date');
    const prayerGregEl = scope.querySelector('#prayer-greg-date');
    const prayerItems = scope.querySelectorAll('.prayer-item-official');

    const loginEl = scope.querySelector('#waed-session-login');
    const ipEl = scope.querySelector('#waed-session-ip');
    const versionEl = scope.querySelector('#waed-session-version');

    // 1) الترحيب الذكي حسب ساعات اليوم
    function getSalutation() {
        const h = new Date().getHours();
        if (h >= 4 && h < 12) return "صباح الخير،";
        if (h >= 12 && h < 17) return "طاب مساؤك،";
        return "مساء الخير،";
    }

    function updateGreeting() {
        if (salutationTimeEl) {
            salutationTimeEl.textContent = getSalutation();
        }
    }
    updateGreeting();

    // 2) جلب اسم الموظف من جلسة Frappe
    if (nameEl) {
        if (typeof frappe !== 'undefined' && frappe.session) {
            if (frappe.session.user === 'Administrator') {
                nameEl.textContent = 'مدير النظام المعتمد';
            } else {
                if (frappe.boot && frappe.boot.user_info && frappe.boot.user_info[frappe.session.user]) {
                    const u = frappe.boot.user_info[frappe.session.user];
                    nameEl.textContent = u.fullname || u.name || frappe.session.user;
                } else if (frappe.call) {
                    frappe.call({
                        method: "frappe.client.get",
                        args: { doctype: "User", name: frappe.session.user },
                        callback(r) {
                            if (r && r.message) {
                                nameEl.textContent = r.message.full_name || r.message.first_name || frappe.session.user;
                            }
                        }
                    });
                } else {
                    nameEl.textContent = frappe.session.user_fullname || frappe.session.user;
                }
            }
        } else {
            nameEl.textContent = 'أحمد النجار';
        }
    }

    // 3) تحديث الساعة والتواريخ الحية
    function tickClock() {
        const now = new Date();
        updateGreeting();

        // الساعة الرقمية
        if (clockEl) {
            clockEl.textContent = now.toLocaleTimeString("en-GB", { 
                hour: "2-digit", 
                minute: "2-digit", 
                second: "2-digit" 
            });
        }

        // نص اليوم والوقت في بطاقة الصلاة (مثل: الأربعاء 5:10 م)
        if (prayerDateTimeEl) {
            const weekday = now.toLocaleDateString("ar-LY", { weekday: "long" });
            const timeStr = now.toLocaleTimeString("ar-LY", { hour: "numeric", minute: "2-digit", hour12: true });
            prayerDateTimeEl.textContent = `${weekday} ${timeStr}`;
        }

        // التاريخ الميلادي
        const gregFormatted = now.toLocaleDateString("ar-LY", { 
            weekday: "long", 
            year: "numeric", 
            month: "long", 
            day: "numeric" 
        });
        if (gregEl) gregEl.textContent = gregFormatted + " م";
        if (prayerGregEl) {
            prayerGregEl.textContent = now.toLocaleDateString("ar-LY", { day: "numeric", month: "long", year: "numeric" });
        }

        // التاريخ الهجري
        try {
            const hijriStr = new Intl.DateTimeFormat("ar-SA", { 
                calendar: "islamic-umalqura", 
                day: "numeric", 
                month: "long", 
                year: "numeric" 
            }).format(now);
            if (hijriEl) hijriEl.textContent = hijriStr + " هـ";
            if (prayerHijriEl) prayerHijriEl.textContent = hijriStr + " هـ";
        } catch (e) {
            const hijriFallback = new Intl.DateTimeFormat('ar-LY-u-ca-islamic', { 
                day: 'numeric', 
                month: 'long', 
                year: 'numeric' 
            }).format(now);
            if (hijriEl) hijriEl.textContent = hijriFallback + " هـ";
            if (prayerHijriEl) prayerHijriEl.textContent = hijriFallback + " هـ";
        }
    }

    const clockTimerId = setInterval(tickClock, 1000);
    tickClock();

    // 4) تفاصيل الجلسة الحقيقية
    if (typeof frappe !== 'undefined' && frappe.boot) {
        let lastLoginStr = "--:--";
        if (frappe.boot.user && frappe.boot.user.last_login) {
            try {
                lastLoginStr = new Intl.DateTimeFormat('ar-LY', { 
                    hour: '2-digit', 
                    minute: '2-digit', 
                    hour12: true 
                }).format(new Date(frappe.boot.user.last_login));
            } catch(e) { 
                lastLoginStr = frappe.boot.user.last_login; 
            }
        }
        
        if (loginEl) loginEl.textContent = lastLoginStr;
        if (ipEl) ipEl.textContent = frappe.boot.user_ip || frappe.boot.ip || "10.0.4.12";
        if (versionEl) {
            versionEl.textContent = frappe.boot.versions && frappe.boot.versions.erpnext 
                ? "ERPNext " + frappe.boot.versions.erpnext 
                : "منظومة واعد v4.2";
        }
    } else {
        if (loginEl) loginEl.textContent = "08:15 ص";
        if (ipEl) ipEl.textContent = "192.168.1.105";
        if (versionEl) versionEl.textContent = "منظومة واعد v4.2 (ERPNext)";
    }

    // 5) حساب مواقيت الصلاة بدقة (الفجر، الشروق، الظهر، العصر، المغرب، العشاء)
    const PRAYER_ORDER = ['Fajr', 'Sunrise', 'Dhuhr', 'Asr', 'Maghrib', 'Isha'];
    let prayerTimesToday = null;
    let prayerLiveTimer = null;

    function to24(t) { return t.split(' ')[0].replace(':', '.'); }

    function buildTodayDates(timings) {
        const today = new Date();
        const dates = {};
        PRAYER_ORDER.forEach(key => {
            const raw = timings[key].split(' ')[0];
            const [h, m] = raw.split(':').map(Number);
            dates[key] = new Date(today.getFullYear(), today.getMonth(), today.getDate(), h, m, 0);
        });
        return dates;
    }

    function updateActivePrayerPill() {
        if (!prayerTimesToday) return;
        const now = new Date();

        let nextKey = null;
        for (let i = 0; i < PRAYER_ORDER.length; i++) {
            if (now < prayerTimesToday[PRAYER_ORDER[i]]) {
                nextKey = PRAYER_ORDER[i];
                break;
            }
        }

        // إذا انتهت جميع صلوات اليوم، فالصلاة القادمة هي فجر الغد
        if (!nextKey) {
            nextKey = 'Fajr';
        }

        prayerItems.forEach(item => {
            const key = item.getAttribute('data-prayer');
            const isNext = (key === nextKey);
            item.classList.toggle('is-next-active', isNext);
        });
    }

    function setPrayerTimings(timings) {
        prayerItems.forEach(item => {
            const key = item.getAttribute('data-prayer');
            const timeEl = item.querySelector('.prayer-time-val');
            if (timeEl && timings[key]) {
                timeEl.textContent = to24(timings[key]);
            }
        });

        prayerTimesToday = buildTodayDates(timings);
        updateActivePrayerPill();
        if (prayerLiveTimer) clearInterval(prayerLiveTimer);
        prayerLiveTimer = setInterval(updateActivePrayerPill, 1000);
    }

    // جلب مواقيت الصلاة من API أو استخدام أوقات طرابلس المعتمدة الموضحة في الصورة
    fetch('https://api.aladhan.com/v1/timingsByCity?city=Tripoli&country=Libya&method=3')
        .then(res => res.json())
        .then(data => {
            if (data && data.data && data.data.timings) {
                setPrayerTimings(data.data.timings);
            }
        })
        .catch(() => {
            // القيم المعتمدة المطابقة للصورة المرفقة تماماً
            setPrayerTimings({
                Fajr: "05:31",
                Sunrise: "06:55",
                Dhuhr: "13:03",
                Asr: "16:26",
                Maghrib: "19:07",
                Isha: "20:26"
            });
        });

    // 6) تنظيف المؤقتات عند مغادرة الصفحة
    if (typeof frappe !== 'undefined' && frappe.ui && frappe.ui.form) {
        frappe.ui.form.on('Custom HTML Block', {
            unload: function() {
                if (clockTimerId) clearInterval(clockTimerId);
                if (prayerLiveTimer) clearInterval(prayerLiveTimer);
            }
        });
    }
})();

style:
@import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+Arabic:wght@300;400;500;600;700;800&family=Readex+Pro:wght@400;500;600;700;800&family=Poppins:wght@400;500;600;700&display=swap');

/* ==============================================================
   الهوية البصرية المعتمدة للهيئة العامة للأوقاف والشؤون الإسلامية
   اللون الكحلي البترولي المعتمد + الخلفية الإسلامية الهندسية الراقية
   ============================================================== */
:root {
    --wq-petrol-dark:     #041D28;
    --wq-petrol-base:     #062E3F;
    --wq-petrol-med:      #083B4E;
    --wq-petrol-light:    #0C4C64;
    --wq-cyan-accent:     #22A3CC;
    --wq-cyan-glow:       rgba(34, 163, 204, 0.35);
    --wq-gold-accent:     #D97706;

    --wq-canvas-bg:       #F8FAFC;
    --wq-card-bg:         #FFFFFF;
    --wq-card-border:     #E2E8F0;
    --wq-card-border-soft:#EEF2F6;
    --wq-text-main:       #062E3F;
    --wq-text-muted:      #64748B;
    --wq-text-subtle:     #94A3B8;

